  settings: {
    mode: "Timed", goal: "money", targetCashByRound: "", roundStart: 1, startingCash: 650,
    mapDifficulty: "Beginner", gameDifficulty: "Medium", players: 1, monkeyKnowledge: true, selectedHero: "quincy",
    maxTowers: 999, maxBananaFarms: 999, maxBoatSpots: 0, lordOfAbyss: 0
  },
  endRound: 40,
  events: [],
  monkeyInstances: {},
  buffs: [],
  paragonHistory: {},
  selectedEventId: null,
  selectedCumulative: null,
  inspectorTab: "action",
  nextEventNumber: 1,
  nextMonkeyNumber: 1,
  nextBuffNumber: 1,
  nextParagonNumber: 1,
  tutorialIndex: 0,
  roundMoneyTicks: {},
  activeRound: 1,
  centerTab: "editor",
  towerIncomeByTower: null,
  towerIncomeCache: new Map(),
  monkeyTimelineCache: new Map(),
  monkeyStateRoundCache: new Map(),
  monkeyStateMomentCache: new Map()
